from pathlib import Path
import base64,gzip,subprocess,tempfile
idx=Path("index.html")
if 'const APP_VERSION = "7.9.9.3";' not in idx.read_text(): raise SystemExit("Expected v7.9.9.3 baseline")
patch=gzip.decompress(base64.b64decode(""))
with tempfile.NamedTemporaryFile(delete=False) as f: f.write(patch); name=f.name
subprocess.run(["patch","-p0","-i",name],check=True)
Path("assets/js/trip-edit-session-service.js").write_bytes(gzip.decompress(base64.b64decode("")))
for fn in ["manifest.json","sw.js"]:
 p=Path(fn);p.write_text(p.read_text().replace("7.9.9.3","7.9.9.4"))
ch=Path("CHANGELOG.md");ch.write_text('# v7.9.9.4 · Phase 3E Add Stop / Add Transit Draft Foundation\n\n* Edit Mode now shows `新增地點` and `新增交通` for each Day.\n* New items stay in the Local Draft and are created only by the final global `儲存` transaction.\n* Adding an item normalizes chronological `sortOrder`, so itinerary and Map draft sequence share the same order.\n* Transit drafts use the existing previous Stop / next Stop routing semantics. Location editing remains a later Phase 3E increment.\n\n'+ch.read_text())